1	// Package indexroom implements chain ingestion with reorg handling.
2	package indexroom
3	
4	import (
5		"fmt"
6		"net"
7		"sort"
8		"strconv"
9		"strings"
10		"unicode"
11	)
12	
13	// Instance is one discoverable service instance.
14	type Instance struct {
15		ID      string
16		Address string
17	}
18	
19	// HealthState is the offline health observation of one instance.
20	// Health is driven entirely by submitted observations; no probing occurs.
21	type HealthState string
22	
23	// Health states.
24	const (
25		HealthUnknown   HealthState = "unknown"
26		HealthHealthy   HealthState = "healthy"
27		HealthUnhealthy HealthState = "unhealthy"
28	)
29	
30	// InstanceView is a snapshot of one instance together with its health observation.
31	type InstanceView struct {
32		ID       string
33		Address  string
34		Health   HealthState
35		Sequence int64
36		Reason   string
37	}
38	
39	// Registration is a validated request that replaces a service's instance list.
40	type Registration struct {
41		Service   string
42		Revision  int
43		Instances []Instance
44	}
45	
46	// HealthUpdate is a validated health observation request.
47	type HealthUpdate struct {
48		Service    string
49		InstanceID string
50		Revision   int
51		Sequence   int64
52		Healthy    bool
53		Reason     string
54	}
55	
56	// ServiceView is an immutable snapshot of one registered service.
57	type ServiceView struct {
58		Service   string
59		Revision  int
60		Instances []InstanceView
61	}
62	
63	// OutcomeKind classifies a failed request.
64	type OutcomeKind string
65	
66	// Outcome kinds.
67	const (
68		OutcomeInvalid   OutcomeKind = "invalid"
69		OutcomeConflict  OutcomeKind = "conflict"
70		OutcomeNotFound  OutcomeKind = "not_found"
71		OutcomeStale     OutcomeKind = "stale"
72		OutcomeNoHealthy OutcomeKind = "no_healthy"
73	)
74	
75	// Outcome is the result of applying one registration against the registry.
76	type Outcome struct {
77		Service  string
78		OK       bool
79		Changed  bool
80		Revision int
81		Kind     OutcomeKind
82		Reason   string
83		Expected int
84		Actual   int
85	}
86	
87	// HealthOutcome is the result of applying one health update against the registry.
88	type HealthOutcome struct {
89		Service    string
90		InstanceID string
91		OK         bool
92		Changed    bool
93		Kind       OutcomeKind
94		Reason     string
95		Revision   int
96		Expected   int
97		Actual     int
98		Sequence   int64
99	}
100	
101	// Selection is a validated request that chooses one healthy target instance.
102	type Selection struct {
103		Service  string
104		Revision int
105	}
106	
107	// SelectOutcome is the result of choosing one healthy instance.
108	//
109	// On success the chosen instance carries its id, address and current health
110	// sequence. A selection never mutates registrations, health records or the
111	// per-service rotation cursor on failure; on success it only advances that
112	// cursor to the chosen instance's id.
113	type SelectOutcome struct {
114		Service    string
115		OK         bool
116		Kind       OutcomeKind
117		Reason     string
118		Revision   int
119		Expected   int
120		Actual     int
121		InstanceID string
122		Address    string
123		Sequence   int64
124	}
125	
126	// Registry is an in-memory service instance registry.
127	type Registry struct {
128		services map[string]*serviceState
129	}
130	
131	type serviceState struct {
132		revision  int
133		instances map[string]*instanceState // instance id -> state
134	
135		// cursor is the id returned by the last successful selection. Selection
136		// starts at the smallest healthy id before any success (cursorSet == false)
137		// and otherwise continues just after cursor. The cursor intentionally
138		// survives registration replacements and health changes: removed instances
139		// and recovered or newly joined instances are located by id in the current
140		// healthy set without restarting the rotation.
141		cursor    string
142		cursorSet bool
143	}
144	
145	type instanceState struct {
146		address  string
147		health   HealthState
148		sequence int64
149		reason   string
150	}
151	
152	// newInstanceState returns a fresh observation: unknown with sequence 0.
153	func newInstanceState(address string) *instanceState {
154		return &instanceState{address: address, health: HealthUnknown}
155	}
156	
157	// NewRegistry returns an empty registry.
158	func NewRegistry() *Registry {
159		return &Registry{services: map[string]*serviceState{}}
160	}
161	
162	// RevisionOf returns the service's current revision, or 0 when it is unknown.
163	func (r *Registry) RevisionOf(service string) int {
164		if st, ok := r.services[service]; ok {
165			return st.revision
166		}
167		return 0
168	}
169	
170	// validateServiceName is the service-identity field shared by every request:
171	// the trimmed name must not be blank.
172	func validateServiceName(service string) (string, error) {
173		name := strings.TrimSpace(service)
174		if name == "" {
175			return "", errInvalid("service name must not be empty")
176		}
177		return name, nil
178	}
179	
180	// validateExpectedRevision is the revision field shared by every request: it
181	// must be a non-negative integer. Callers check their remaining content fields
182	// after this one, so content validity is fully established before any revision
183	// comparison against the registry.
184	func validateExpectedRevision(revision int) error {
185		if revision < 0 {
186			return errInvalid("expectedRevision must be a non-negative integer")
187		}
188		return nil
189	}
190	
191	// revisionFailure describes the common revision-gate result shared by health
192	// observations and selections. It carries no operation-specific fields: each
193	// operation maps it onto its own result so stale health sequences, missing
194	// instances and missing healthy targets never get mixed together.
195	type revisionFailure struct {
196		kind     OutcomeKind
197		reason   string
198		revision int // current revision (0 for an unknown service)
199		expected int
200		actual   int
201	}
202	
203	// checkServiceRevision applies the gate the health and select operations share.
204	// Content validation has already happened by the time it runs, so an invalid
205	// field never reaches it. It first looks the service up (an unknown service is
206	// at revision 0) and compares revisions: a mismatch is a conflict carrying the
207	// request's expectedRevision and the actual revision, even when the service or
208	// the targeted instance is missing. With matching revisions an unknown service
209	// is not_found; a registered service with an empty instance list is still
210	// returned, so it compares by its real revision rather than being treated as
211	// absent. Returning nil means the gate passed and the caller owns the rest.
212	func (r *Registry) checkServiceRevision(service string, expected int) (*serviceState, *revisionFailure) {
213		st, exists := r.services[service]
214		actual := 0
215		if exists {
216			actual = st.revision
217		}
218		if expected != actual {
219			return nil, &revisionFailure{
220				kind:     OutcomeConflict,
221				reason:   fmt.Sprintf("service %q is at revision %d, not %d", service, actual, expected),
222				revision: actual,
223				expected: expected,
224				actual:   actual,
225			}
226		}
227		if !exists {
228			return nil, &revisionFailure{
229				kind:     OutcomeNotFound,
230				reason:   fmt.Sprintf("service %q does not exist", service),
231				revision: 0,
232			}
233		}
234		return st, nil
235	}
236	
237	// asHealth maps the shared revision gate failure onto a health result. The
238	// operation-specific fields (instance id and the current sequence) stay zero so
239	// they remain omitted exactly as health's own revision failures always have.
240	func (f *revisionFailure) asHealth(service string) HealthOutcome {
241		return HealthOutcome{
242			Service:  service,
243			OK:       false,
244			Kind:     f.kind,
245			Reason:   f.reason,
246			Revision: f.revision,
247			Expected: f.expected,
248			Actual:   f.actual,
249		}
250	}
251	
252	// asSelect maps the shared revision gate failure onto a selection result, which
253	// never fabricates an instance id, address or sequence on rejection.
254	func (f *revisionFailure) asSelect(service string) SelectOutcome {
255		return SelectOutcome{
256			Service:  service,
257			OK:       false,
258			Kind:     f.kind,
259			Reason:   f.reason,
260			Revision: f.revision,
261			Expected: f.expected,
262			Actual:   f.actual,
263		}
264	}
265	
266	// ValidateRegistration trims and validates one request without mutating the registry.
267	// Content validity is established before any revision check.
268	func (r *Registry) ValidateRegistration(service string, revision int, instances []Instance) (Registration, error) {
269		name, err := validateServiceName(service)
270		if err != nil {
271			return Registration{}, err
272		}
273		if err := validateExpectedRevision(revision); err != nil {
274			return Registration{}, err
275		}
276		seen := make(map[string]bool, len(instances))
277		valid := make([]Instance, 0, len(instances))
278		for _, inst := range instances {
279			id := strings.TrimSpace(inst.ID)
280			if id == "" {
281				return Registration{}, errInvalid("instance id must not be empty")
282			}
283			if seen[id] {
284				return Registration{}, errInvalid(fmt.Sprintf("duplicate instance id %q", id))
285			}
286			addr, err := parseAddress(inst.Address)
287			if err != nil {
288				return Registration{}, errInvalid(err.Error())
289			}
290			seen[id] = true
291			valid = append(valid, Instance{ID: id, Address: addr})
292		}
293		return Registration{Service: name, Revision: revision, Instances: valid}, nil
294	}
295	
296	// Apply checks the revision and, on match, replaces the service's instance list.
297	// A new service is created at revision 1 only when expectedRevision is 0.
298	// A matching registration with identical content succeeds without bumping revision.
299	func (r *Registry) Apply(reg Registration) Outcome {
300		st, exists := r.services[reg.Service]
301		if !exists {
302			if reg.Revision != 0 {
303				return Outcome{
304					Service:  reg.Service,
305					OK:       false,
306					Kind:     OutcomeConflict,
307					Reason:   fmt.Sprintf("service %q does not exist yet; expected revision must be 0, got %d", reg.Service, reg.Revision),
308					Expected: reg.Revision,
309					Actual:   0,
310					Revision: 0,
311				}
312			}
313			st = &serviceState{revision: 1, instances: make(map[string]*instanceState, len(reg.Instances))}
314			r.services[reg.Service] = st
315			for _, inst := range reg.Instances {
316				st.instances[inst.ID] = newInstanceState(inst.Address)
317			}
318			return Outcome{Service: reg.Service, OK: true, Changed: true, Revision: 1}
319		}
320		if reg.Revision != st.revision {
321			return Outcome{
322				Service:  reg.Service,
323				OK:       false,
324				Kind:     OutcomeConflict,
325				Reason:   fmt.Sprintf("service %q is at revision %d, not %d", reg.Service, st.revision, reg.Revision),
326				Expected: reg.Revision,
327				Actual:   st.revision,
328				Revision: st.revision,
329			}
330		}
331		changed := !sameInstances(st.instances, reg.Instances)
332		if changed {
333			// A replacement fully rebuilds the list, but an instance that keeps both
334			// its id and its address retains its health observation. Anything new,
335			// address-changed, or removed-then-readded starts from unknown at sequence 0.
336			next := make(map[string]*instanceState, len(reg.Instances))
337			for _, inst := range reg.Instances {
338				if old, ok := st.instances[inst.ID]; ok && old.address == inst.Address {
339					next[inst.ID] = old
340				} else {
341					next[inst.ID] = newInstanceState(inst.Address)
342				}
343			}
344			st.instances = next
345			st.revision++
346		}
347		return Outcome{Service: reg.Service, OK: true, Changed: changed, Revision: st.revision}
348	}
349	
350	// ValidateHealth trims and validates one health observation without mutating
351	// the registry. Content validity is established before any revision check.
352	func (r *Registry) ValidateHealth(service, instanceID string, revision int, sequence int64, healthy bool, reason string) (HealthUpdate, error) {
353		name, err := validateServiceName(service)
354		if err != nil {
355			return HealthUpdate{}, err
356		}
357		id := strings.TrimSpace(instanceID)
358		if id == "" {
359			return HealthUpdate{}, errInvalid("instance id must not be empty")
360		}
361		if err := validateExpectedRevision(revision); err != nil {
362			return HealthUpdate{}, err
363		}
364		if sequence <= 0 {
365			return HealthUpdate{}, errInvalid("sequence must be a positive integer")
366		}
367		normalizedReason := strings.TrimSpace(reason)
368		if healthy {
369			// A healthy observation carries no reason.
370			normalizedReason = ""
371		} else if normalizedReason == "" {
372			return HealthUpdate{}, errInvalid("reason must not be empty when unhealthy")
373		}
374		return HealthUpdate{
375			Service:    name,
376			InstanceID: id,
377			Revision:   revision,
378			Sequence:   sequence,
379			Healthy:    healthy,
380			Reason:     normalizedReason,
381		}, nil
382	}
383	
384	// ApplyHealth records an offline observation once the shared revision gate has
385	// passed.
386	//
387	// The gate is shared with Select (see checkServiceRevision): a revision
388	// mismatch is a conflict carrying the request and current revisions even when
389	// the service or the targeted instance is missing, and a matching request for
390	// an unknown service is not_found. Only after it does health apply its own
391	// rules:
392	//   - a missing instance is not_found;
393	//   - a sequence below the accepted one is stale and reports the current sequence;
394	//   - the same sequence with identical normalized status and reason succeeds
395	//     without changing state;
396	//   - the same sequence with different content is a conflict;
397	//   - a newer sequence writes the status and reason.
398	func (r *Registry) ApplyHealth(upd HealthUpdate) HealthOutcome {
399		st, fail := r.checkServiceRevision(upd.Service, upd.Revision)
400		if fail != nil {
401			return fail.asHealth(upd.Service)
402		}
403		cur, ok := st.instances[upd.InstanceID]
404		if !ok {
405			return HealthOutcome{
406				Service:    upd.Service,
407				InstanceID: upd.InstanceID,
408				OK:         false,
409				Kind:       OutcomeNotFound,
410				Reason:     fmt.Sprintf("instance %q does not exist in service %q", upd.InstanceID, upd.Service),
411				Revision:   st.revision,
412			}
413		}
414		if upd.Sequence < cur.sequence {
415			return HealthOutcome{
416				Service:    upd.Service,
417				InstanceID: upd.InstanceID,
418				OK:         false,
419				Kind:       OutcomeStale,
420				Reason:     fmt.Sprintf("sequence %d is older than the current sequence %d", upd.Sequence, cur.sequence),
421				Revision:   st.revision,
422				Sequence:   cur.sequence,
423			}
424		}
425		if upd.Sequence == cur.sequence {
426			want := HealthUnhealthy
427			if upd.Healthy {
428				want = HealthHealthy
429			}
430			if cur.health == want && cur.reason == upd.Reason {
431				return HealthOutcome{
432					Service:    upd.Service,
433					InstanceID: upd.InstanceID,
434					OK:         true,
435					Changed:    false,
436					Revision:   st.revision,
437					Sequence:   cur.sequence,
438				}
439			}
440			return HealthOutcome{
441				Service:    upd.Service,
442				InstanceID: upd.InstanceID,
443				OK:         false,
444				Kind:       OutcomeConflict,
445				Reason:     fmt.Sprintf("sequence %d already used with different health content", upd.Sequence),
446				Revision:   st.revision,
447				Sequence:   cur.sequence,
448			}
449		}
450		// Newer sequence: record the observation. Health updates never bump the
451		// registration revision.
452		if upd.Healthy {
453			cur.health = HealthHealthy
454			cur.reason = ""
455		} else {
456			cur.health = HealthUnhealthy
457			cur.reason = upd.Reason
458		}
459		cur.sequence = upd.Sequence
460		return HealthOutcome{
461			Service:    upd.Service,
462			InstanceID: upd.InstanceID,
463			OK:         true,
464			Changed:    true,
465			Revision:   st.revision,
466			Sequence:   cur.sequence,
467		}
468	}
469	
470	// ValidateSelection trims and validates one select request without touching
471	// the registry. Content validity is established before any revision check.
472	func (r *Registry) ValidateSelection(service string, revision int) (Selection, error) {
473		name, err := validateServiceName(service)
474		if err != nil {
475			return Selection{}, err
476		}
477		if err := validateExpectedRevision(revision); err != nil {
478			return Selection{}, err
479		}
480		return Selection{Service: name, Revision: revision}, nil
481	}
482	
483	// Select chooses one healthy instance for the service once the shared revision
484	// gate has passed.
485	//
486	// The gate is shared with ApplyHealth (see checkServiceRevision): a mismatch is
487	// a conflict carrying the request and current revisions (an unknown service is
488	// at revision 0), and a matching request for an unknown service is not_found.
489	// Only after it does select apply its own rule: an existing service with no
490	// healthy instance is no_healthy and no address is fabricated. A registered
491	// service with an empty instance list still compares by its real revision; the
492	// gate hands it through so the answer is no_healthy, not not_found.
493	//
494	// Healthy instances rotate per service by ascending instance id: the first
495	// success takes the smallest id and each later success continues just after
496	// the previously chosen id, wrapping to the smallest id past the end. With a
497	// single healthy instance it may be chosen repeatedly. Registrations and
498	// health changes alter the candidate set immediately but never reset the
499	// rotation; failed selections leave the cursor where it was.
500	func (r *Registry) Select(sel Selection) SelectOutcome {
501		st, fail := r.checkServiceRevision(sel.Service, sel.Revision)
502		if fail != nil {
503			return fail.asSelect(sel.Service)
504		}
505	
506		healthy := make([]string, 0, len(st.instances))
507		for id, cur := range st.instances {
508			if cur.health == HealthHealthy {
509				healthy = append(healthy, id)
510			}
511		}
512		sort.Strings(healthy)
513		if len(healthy) == 0 {
514			return SelectOutcome{
515				Service:  sel.Service,
516				OK:       false,
517				Kind:     OutcomeNoHealthy,
518				Reason:   fmt.Sprintf("service %q has no healthy instance available", sel.Service),
519				Revision: st.revision,
520			}
521		}
522	
523		chosen := healthy[0]
524		if st.cursorSet {
525			chosen = healthy[0]
526			for _, id := range healthy {
527				if id > st.cursor {
528					chosen = id
529					break
530				}
531			}
532		}
533		cur := st.instances[chosen]
534		st.cursor = chosen
535		st.cursorSet = true
536		return SelectOutcome{
537			Service:    sel.Service,
538			OK:         true,
539			Revision:   st.revision,
540			InstanceID: chosen,
541			Address:    cur.address,
542			Sequence:   cur.sequence,
543		}
544	}
545	
546	// Snapshot returns all services sorted by name, with instances sorted by id.
547	func (r *Registry) Snapshot() []ServiceView {
548		names := make([]string, 0, len(r.services))
549		for name := range r.services {
550			names = append(names, name)
551		}
552		sort.Strings(names)
553		views := make([]ServiceView, 0, len(names))
554		for _, name := range names {
555			st := r.services[name]
556			ids := make([]string, 0, len(st.instances))
557			for id := range st.instances {
558				ids = append(ids, id)
559			}
560			sort.Strings(ids)
561			instances := make([]InstanceView, 0, len(ids))
562			for _, id := range ids {
563				cur := st.instances[id]
564				instances = append(instances, InstanceView{
565					ID:       id,
566					Address:  cur.address,
567					Health:   cur.health,
568					Sequence: cur.sequence,
569					Reason:   cur.reason,
570				})
571			}
572			views = append(views, ServiceView{Service: name, Revision: st.revision, Instances: instances})
573		}
574		return views
575	}
576	
577	func sameInstances(current map[string]*instanceState, incoming []Instance) bool {
578		if len(current) != len(incoming) {
579			return false
580		}
581		for _, inst := range incoming {
582			if old, ok := current[inst.ID]; !ok || old.address != inst.Address {
583				return false
584			}
585		}
586		return true
587	}
588	
589	// parseAddress validates a host:port address: domains, IPv4 and bracketed IPv6.
590	// No network I/O is performed.
591	func parseAddress(raw string) (string, error) {
592		addr := strings.TrimSpace(raw)
593		if addr == "" {
594			return "", fmt.Errorf("instance address must not be empty")
595		}
596		for _, r := range addr {
597			if unicode.IsSpace(r) || unicode.IsControl(r) {
598				return "", fmt.Errorf("instance address %q must not contain whitespace or control characters", addr)
599			}
600		}
601		host, port, err := net.SplitHostPort(addr)
602		if err != nil {
603			return "", fmt.Errorf("instance address %q is not a host:port address: %v", addr, err)
604		}
605		if host == "" {
606			return "", fmt.Errorf("instance address %q has an empty host", addr)
607		}
608		if !allDigits(port) {
609			return "", fmt.Errorf("instance address %q port %q must be a decimal integer", addr, port)
610		}
611		n, err := strconv.Atoi(port)
612		if err != nil {
613			return "", fmt.Errorf("instance address %q port %q must be a decimal integer", addr, port)
614		}
615		if n < 1 || n > 65535 {
616			return "", fmt.Errorf("instance address %q port %d is out of range (1-65535)", addr, n)
617		}
618		if strings.HasPrefix(addr, "[") {
619			ip := net.ParseIP(host)
620			if ip == nil || !strings.Contains(host, ":") {
621				return "", fmt.Errorf("instance address %q bracketed host is not a valid IPv6 address", addr)
622			}
623		} else if ip := net.ParseIP(host); ip != nil {
624			if ip.To4() == nil {
625				return "", fmt.Errorf("instance address %q IPv6 addresses must be bracketed", addr)
626			}
627		} else if !isDomainName(host) {
628			return "", fmt.Errorf("instance address %q host %q is not a valid domain, IPv4 or bracketed IPv6", addr, host)
629		}
630		return addr, nil
631	}
632	
633	func allDigits(s string) bool {
634		if s == "" {
635			return false
636		}
637		for _, r := range s {
638			if r < '0' || r > '9' {
639				return false
640			}
641		}
642		return true
643	}
644	
645	// isDomainName validates a dotted hostname with alphanumeric/hyphen labels.
646	func isDomainName(host string) bool {
647		if len(host) > 253 {
648			return false
649		}
650		for _, label := range strings.Split(host, ".") {
651			n := len(label)
652			if n == 0 || n > 63 {
653				return false
654			}
655			if label[0] == '-' || label[n-1] == '-' {
656				return false
657			}
658			for _, r := range label {
659				if r == '-' ||
660					(r >= 'a' && r <= 'z') ||
661					(r >= 'A' && r <= 'Z') ||
662					(r >= '0' && r <= '9') {
663					continue
664				}
665				return false
666			}
667		}
668		return true
669	}
