176	// registerProcessor runs the request batch in input order. Failed items keep
177	// their slot in results and set failed; later items still run against the
178	// state committed by earlier successful items.
179	type registerProcessor struct {
180		registry *indexroom.Registry
181		results  []registerResult
182		failed   bool
183	}
184	
185	// invalid records an input-validation failure for an item. Content validity is
186	// checked before any business rule, so the revision stamped here is the
187	// service's current revision when the item is handled.
188	func (p *registerProcessor) invalid(service, reason string) {
189		p.failed = true
190		p.results = append(p.results, registerResult{
191			Service:  service,
192			OK:       false,
193			Error:    "invalid",
194			Reason:   reason,
195			Revision: p.registry.RevisionOf(service),
196		})
197	}
198	
199	// invalidf is invalid with a formatted reason.
200	func (p *registerProcessor) invalidf(service, format string, args ...any) {
201		p.invalid(service, fmt.Sprintf(format, args...))
202	}
203	
204	// reject records a business-rule failure (conflict, not_found, stale or
205	// no_healthy), keeping each operation's distinct result fields. Health
206	// rejections additionally carry the current sequence; register and select
207	// pass 0 so it stays omitted.
208	func (p *registerProcessor) reject(service string, kind indexroom.OutcomeKind, reason string, revision, expected, actual int, sequence int64) {
209		p.failed = true
210		p.results = append(p.results, registerResult{
211			Service:          service,
212			OK:               false,
213			Error:            string(kind),
214			Reason:           reason,
215			Revision:         revision,
216			ExpectedRevision: expected,
217			ActualRevision:   actual,
218			Sequence:         sequence,
219		})
220	}
221	
222	// succeed records an accepted item; omitempty keeps zero-valued fields out of
223	// the output exactly as before the refactor.
224	func (p *registerProcessor) succeed(result registerResult) {
225		result.OK = true
226		p.results = append(p.results, result)
227	}
228	
229	// registerRequest processes one register request, appending its outcome.
230	func (p *registerProcessor) registerRequest(raw json.RawMessage, service string) {
231		var req struct {
232			Service   string          `json:"service"`
233			Revision  *int64          `json:"expectedRevision"`
234			Instances json.RawMessage `json:"instances"`
235		}
236		if err := json.Unmarshal(raw, &req); err != nil {
237			p.invalidf(service, "request must be an object with service, expectedRevision and instances: %v", err)
238			return
239		}
240		service = strings.TrimSpace(req.Service)
241	
242		if req.Revision == nil {
243			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
244			return
245		}
246		if !isJSONArray(req.Instances) {
247			p.invalid(service, "instances must be an array")
248			return
249		}
250		var instances []indexroom.Instance
251		if err := json.Unmarshal(req.Instances, &instances); err != nil {
252			p.invalidf(service, "instances must be an array of objects with id and address: %v", err)
253			return
254		}
255	
256		registration, err := p.registry.ValidateRegistration(service, int(*req.Revision), instances)
257		if err != nil {
258			p.invalid(service, err.Error())
259			return
260		}
261	
262		outcome := p.registry.Apply(registration)
263		if !outcome.OK {
264			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
265			return
266		}
267		p.succeed(registerResult{
268			Service:  outcome.Service,
269			Changed:  outcome.Changed,
270			Revision: outcome.Revision,
271		})
272	}
273	
274	// healthRequest processes one health observation request, appending its outcome.
275	func (p *registerProcessor) healthRequest(raw json.RawMessage, service string) {
276		var req struct {
277			Service    string  `json:"service"`
278			InstanceID string  `json:"instanceId"`
279			Revision   *int64  `json:"expectedRevision"`
280			Sequence   *int64  `json:"sequence"`
281			Healthy    *bool   `json:"healthy"`
282			Reason     *string `json:"reason"`
283		}
284		if err := json.Unmarshal(raw, &req); err != nil {
285			p.invalidf(service, "health request must be an object with service, instanceId, expectedRevision, sequence and healthy: %v", err)
286			return
287		}
288		service = strings.TrimSpace(req.Service)
289	
290		if req.Revision == nil {
291			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
292			return
293		}
294		if req.Sequence == nil {
295			p.invalid(service, "sequence is required and must be a positive integer")
296			return
297		}
298		if req.Healthy == nil {
299			p.invalid(service, "healthy is required and must be a boolean")
300			return
301		}
302		reason := ""
303		if req.Reason != nil {
304			reason = *req.Reason
305		}
306	
307		update, err := p.registry.ValidateHealth(service, req.InstanceID, int(*req.Revision), *req.Sequence, *req.Healthy, reason)
308		if err != nil {
309			p.invalid(service, err.Error())
310			return
311		}
312	
313		outcome := p.registry.ApplyHealth(update)
314		if !outcome.OK {
315			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, outcome.Sequence)
316			return
317		}
318		p.succeed(registerResult{
319			Service:  outcome.Service,
320			Changed:  outcome.Changed,
321			Revision: outcome.Revision,
322			Sequence: outcome.Sequence,
323		})
324	}
325	
326	// selectRequest processes one select request, appending its outcome.
327	// A selection performs no network access and never alters registrations or
328	// health records; it only advances the service's healthy-instance rotation.
329	func (p *registerProcessor) selectRequest(raw json.RawMessage, service string) {
330		var req struct {
331			Service  string `json:"service"`
332			Revision *int64 `json:"expectedRevision"`
333		}
334		if err := json.Unmarshal(raw, &req); err != nil {
335			p.invalidf(service, "select request must be an object with service and expectedRevision: %v", err)
336			return
337		}
338		service = strings.TrimSpace(req.Service)
339	
340		if req.Revision == nil {
341			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
342			return
343		}
344	
345		selection, err := p.registry.ValidateSelection(service, int(*req.Revision))
346		if err != nil {
347			p.invalid(service, err.Error())
348			return
349		}
350	
351		outcome := p.registry.Select(selection)
352		if !outcome.OK {
353			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
354			return
355		}
356		p.succeed(registerResult{
357			Service:    outcome.Service,
358			Revision:   outcome.Revision,
359			InstanceID: outcome.InstanceID,
360			Address:    outcome.Address,
361			Sequence:   outcome.Sequence,
362		})
363	}
364	
365	// failRegister emits a top-level input error and returns exit code 1.
366	func failRegister(reason string) int {
367		writeRegisterOutput(struct {
368			Error string `json:"error"`
369		}{Error: reason})
370		return 1
371	}
372	
373	func writeRegisterOutput(v any) {
374		enc := json.NewEncoder(os.Stdout)
375		enc.SetIndent("", "  ")
376		_ = enc.Encode(v)
377	}
378	
379	// isJSONArray reports whether raw is a JSON array (ignoring leading whitespace).
380	func isJSONArray(raw json.RawMessage) bool {
381		for _, b := range raw {
382			switch b {
383			case ' ', '\t', '\n', '\r':
384				continue
385			case '[':
386				return true
387			default:
388				return false
389			}
390		}
391		return false
392	}
393	
394	func runDemo() {
395		index := indexroom.New()
396		blocks := []indexroom.Block{
397			{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1", "t2"}},
398			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t3"}},
399		}
400		for _, block := range blocks {
401			if err := index.Append(block); err != nil {
402				fmt.Printf("append refused at height %d: %v\n", block.Height, err)
403				continue
404			}
405			fmt.Printf("indexed height=%d txs=%d\n", block.Height, len(block.Txs))
406		}
407		if err := index.Append(indexroom.Block{Height: 3, Hash: "h3", Parent: "h1"}); err != nil {
408			fmt.Println("non-linear block refused:", err)
409		}
410		dropped, err := index.Reorg([]indexroom.Block{{Height: 2, Hash: "h2b", Parent: "h1", Txs: []string{"t4", "t5"}}})
411		fmt.Printf("reorg dropped=%v err=%v tip=%d\n", dropped, err, index.Tip)
412	}
