796		// Stale: sequence below the accepted 7. The failure states the reason and
797		// the currently accepted sequence, and keeps the service revision.
798		if r := got.Results[4]; r.OK || r.Error != "stale" ||
799			r.Reason != "sequence 3 is older than the current sequence 7" ||
800			r.Sequence != 7 || r.Revision != 1 {
801			t.Fatalf("stale report: %+v", r)
802		}
803		// Conflict: the accepted sequence 7 reused with the opposite health state.
804		if r := got.Results[5]; r.OK || r.Error != "conflict" ||
805			r.Reason != "sequence 7 already used with different health content" ||
806			r.Sequence != 7 || r.Revision != 1 {
807			t.Fatalf("conflicting report: %+v", r)
808		}
809		// The rejected "unhealthy" reports did not knock b out: the rotation
810		// continues just after a and lands on b with its accepted record.
811		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 7 || r.Revision != 1 {
812			t.Fatalf("select after rejections should still choose b: %+v", r)
813		}
814		// Past the end the rotation wraps to the smallest id.
815		if r := got.Results[7]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 5 {
816			t.Fatalf("select should wrap to a: %+v", r)
817		}
818		// The final list shows only the accepted observations; nothing from the
819		// rejected reports leaked in.
820		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
821			t.Fatalf("services: %+v", got.Services)
822		}
823		insts := got.Services[0].Instances
824		if len(insts) != 2 {
825			t.Fatalf("instances: %+v", insts)
826		}
827		if insts[0].ID != "a" || insts[0].Health != "healthy" || insts[0].Sequence != 5 || insts[0].Reason != "" {
828			t.Fatalf("a should keep its accepted record: %+v", insts[0])
829		}
830		if insts[1].ID != "b" || insts[1].Health != "healthy" || insts[1].Sequence != 7 || insts[1].Reason != "" {
831			t.Fatalf("b should keep its accepted record: %+v", insts[1])
832		}
833	}
