431	func TestRegistryHealthPreservedAcrossRegistration(t *testing.T) {
432		r := NewRegistry()
433		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h:1"}, {ID: "b", Address: "h:2"}})
434	
435		// Observe both instances.
436		upd, _ := r.ValidateHealth("svc", "a", 1, 1, true, "")
437		r.ApplyHealth(upd)
438		upd, _ = r.ValidateHealth("svc", "b", 1, 2, false, "down")
439		r.ApplyHealth(upd)
440	
441		// Re-register with identical content: health and revision preserved.
442		reg, _ := r.ValidateRegistration("svc", 1, []Instance{{ID: "b", Address: "h:2"}, {ID: "a", Address: "h:1"}})
443		out := r.Apply(reg)
444		if !out.OK || out.Changed || out.Revision != 1 {
445			t.Fatalf("identical re-registration: %+v", out)
446		}
447		if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthHealthy || inst.Sequence != 1 {
448			t.Fatalf("a health not preserved: %+v", inst)
449		}
450		if inst := instanceHealth(t, r, "svc", "b"); inst.Health != HealthUnhealthy || inst.Sequence != 2 || inst.Reason != "down" {
451			t.Fatalf("b health not preserved: %+v", inst)
452		}
453	
454		// Address change resets to unknown/0.
455		reg, _ = r.ValidateRegistration("svc", 1, []Instance{{ID: "a", Address: "h:9"}, {ID: "b", Address: "h:2"}})
456		out = r.Apply(reg)
457		if !out.OK || !out.Changed || out.Revision != 2 {
458			t.Fatalf("address change: %+v", out)
459		}
460		if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthUnknown || inst.Sequence != 0 {
461			t.Fatalf("a should reset after address change: %+v", inst)
462		}
463		// b kept its address, so its observation survives.
464		if inst := instanceHealth(t, r, "svc", "b"); inst.Health != HealthUnhealthy || inst.Sequence != 2 {
465			t.Fatalf("b should keep health: %+v", inst)
466		}
467	
468		// A health result collected under the old revision is rejected even though
469		// the instance and its new address exist.
470		upd, _ = r.ValidateHealth("svc", "a", 1, 3, true, "")
471		hout := r.ApplyHealth(upd)
472		if hout.OK || hout.Kind != OutcomeConflict || hout.Actual != 2 {
473			t.Fatalf("old revision result: %+v", hout)
474		}
475	
476		// New revision accepts the observation on the reset instance.
477		upd, _ = r.ValidateHealth("svc", "a", 2, 3, true, "")
478		hout = r.ApplyHealth(upd)
479		if !hout.OK || !hout.Changed || hout.Sequence != 3 {
480			t.Fatalf("new revision result: %+v", hout)
481		}
482	}
