765		if err != nil || sel.Service != "svc" || sel.Revision != 0 {
766			t.Fatalf("trim/valid: %+v err=%v", sel, err)
767		}
768	}
769	
770	// TestSharedRevisionGateEmptyInstanceService locks the rule shared by health
771	// and select: a registered service whose instance list is empty still compares
772	// by its real revision instead of being treated as absent.
773	func TestSharedRevisionGateEmptyInstanceService(t *testing.T) {
774		r := NewRegistry()
775		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h:1"}})
776		registerService(t, r, "svc", 1, nil) // empty list bumps to revision 2
777	
778		// Both operations, wrong expected revision against the empty service: a
779		// conflict carrying the real revision, not not_found at revision 0.
780		upd, _ := r.ValidateHealth("svc", "a", 1, 1, true, "")
781		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeConflict ||
782			out.Expected != 1 || out.Actual != 2 || out.Revision != 2 {
783			t.Fatalf("health empty-service conflict: %+v", out)
784		}
785		sel, _ := r.ValidateSelection("svc", 1)
786		if out := r.Select(sel); out.OK || out.Kind != OutcomeConflict ||
787			out.Expected != 1 || out.Actual != 2 || out.Revision != 2 {
788			t.Fatalf("select empty-service conflict: %+v", out)
789		}
790	
791		// Matching revision: the gate passes. Health then reports the missing
792		// instance (its own not_found), while select reports no_healthy; the two
793		// business results must not be mixed.
794		upd, _ = r.ValidateHealth("svc", "a", 2, 1, true, "")
795		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeNotFound || out.Revision != 2 {
796			t.Fatalf("health through gate on empty service: %+v", out)
797		}
798		sel, _ = r.ValidateSelection("svc", 2)
799		if out := r.Select(sel); out.OK || out.Kind != OutcomeNoHealthy ||
800			out.Revision != 2 || out.InstanceID != "" || out.Address != "" {
801			t.Fatalf("select through gate on empty service: %+v", out)
802		}
803	}
804	
805	// TestSharedRevisionGateConflictPrecedesHealthBusinessRules locks that a
806	// revision mismatch on a health request is reported as conflict even when the
807	// instance is missing or the carried sequence is larger than anything seen.
808	func TestSharedRevisionGateConflictPrecedesHealthBusinessRules(t *testing.T) {
809		r := NewRegistry()
810		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h:1"}})
811		markHealth(t, r, "svc", "a", 1, 5, true, "")
812	
813		// Missing instance plus a larger sequence, wrong revision: conflict first.
814		upd, _ := r.ValidateHealth("svc", "ghost", 9, 100, true, "")
815		out := r.ApplyHealth(upd)
816		if out.OK || out.Kind != OutcomeConflict || out.Expected != 9 ||
817			out.Actual != 1 || out.Revision != 1 {
818			t.Fatalf("missing instance must not mask revision conflict: %+v", out)
819		}
820	
821		// Existing instance with a larger sequence, wrong revision: still conflict;
822		// the observation must not have been written.
823		upd, _ = r.ValidateHealth("svc", "a", 2, 100, false, "down")
824		out = r.ApplyHealth(upd)
825		if out.OK || out.Kind != OutcomeConflict || out.Expected != 2 || out.Actual != 1 {
826			t.Fatalf("larger sequence must not mask revision conflict: %+v", out)
827		}
828		if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthHealthy || inst.Sequence != 5 {
829			t.Fatalf("observation written despite conflict: %+v", inst)
830		}
831	
832		// Unknown service with a non-zero expected revision conflicts even though
833		// the instance cannot exist; expected 0 on the same unknown service is the
834		// operation-specific not_found.
835		upd, _ = r.ValidateHealth("other", "a", 3, 100, true, "")
836		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeConflict ||
837			out.Expected != 3 || out.Actual != 0 || out.Revision != 0 {
838			t.Fatalf("unknown service wrong revision: %+v", out)
839		}
840		upd, _ = r.ValidateHealth("other", "a", 0, 1, true, "")
841		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeNotFound || out.Revision != 0 {
842			t.Fatalf("unknown service expected 0: %+v", out)
843		}
844	}
845	
846	// TestSharedRevisionGateValidationPrecedesRevision locks the ordering shared by
847	// both operations: own-field validity is judged before the revision comparison
848	// even when the service is absent, so the answer is invalid rather than
849	// conflict or not_found.
850	func TestSharedRevisionGateValidationPrecedesRevision(t *testing.T) {
851		r := NewRegistry()
852	
853		if _, err := r.ValidateHealth("   ", "a", 5, 1, true, ""); err == nil {
854			t.Fatalf("blank service health should be invalid before the revision check")
855		}
856		if _, err := r.ValidateHealth("missing", "a", -1, 1, true, ""); err == nil {
857			t.Fatalf("negative revision health should be invalid")
858		}
859		if _, err := r.ValidateSelection("   ", 5); err == nil {
860			t.Fatalf("blank service select should be invalid before the revision check")
861		}
862		if _, err := r.ValidateSelection("missing", -1); err == nil {
863			t.Fatalf("negative revision select should be invalid")
864		}
865	}
